import { css } from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';

/** @deprecated Shared FlattenSimpleInterpolation for tables rounded corner is going to be removed in the future.  */

export const sharedTableStylesCss = css`
  .strato-table-header {
    background: ${Colors.Background.Field.Neutral.Emphasized};
  }

  .strato-table-header-cell {
    font-family: ${Typography.Text.Base.Emphasized.Family};
    font-size: ${Typography.Text.Base.Emphasized.Size};
    font-weight: ${Typography.Text.Base.Emphasized.Weight};
    line-height: ${Typography.Text.Base.Emphasized.LineHeight};
    text-decoration: ${Typography.Text.Base.Emphasized.TextDecoration};
    text-transform: ${Typography.Text.Base.Emphasized.TextTransform};

    color: ${Colors.Text.Neutral.Default};
    padding: ${Spacings.Size6} ${Spacings.Size12};
    border: 0;
  }

  .strato-table-row-even .strato-table-cell {
    background: ${Colors.Background.Container.Neutral.Default};
  }

  .strato-table-cell {
    border: 0;
    color: ${Colors.Text.Neutral.Default};
    font-family: ${Typography.Text.Base.Default.Family};
    font-size: ${Typography.Text.Base.Default.Size};
    font-weight: ${Typography.Text.Base.Default.Weight};
    line-height: ${Typography.Text.Base.Default.LineHeight};
    text-decoration: ${Typography.Text.Base.Default.TextDecoration};
    text-transform: ${Typography.Text.Base.Default.TextTransform};
    padding: ${Spacings.Size12};
  }

  .strato-table-cell + .strato-table-cell {
    border-left-width: ${Borders.Width.Default};
    border-left-style: ${Borders.Style.Default};
    border-left-color: ${Colors.Border.Neutral.Default};
  }

  .strato-table-cell-selectable + .strato-table-cell,
  .strato-table-cell-expandable + .strato-table-cell {
    border-left: none;
  }

  .strato-table-cell-expandable {
    padding: ${Spacings.Size12} ${Spacings.Size6};
  }

  /** Column alignment */
  .strato-table-cell-alignment-left {
    text-align: start;
    justify-content: flex-start;
  }
  .strato-table-cell-alignment-center {
    text-align: center;
    justify-content: center;
  }
  .strato-table-cell-alignment-right {
    text-align: end;
    justify-content: flex-end;
  }

  .strato-table-row-expanded {
    border-top: ${Borders.Width.Emphasized} ${Borders.Style.Default}
      ${Colors.Border.Primary.Accent};

    + .strato-table-row-expandable {
      border-bottom: ${Borders.Width.Emphasized} ${Borders.Style.Default}
        ${Colors.Border.Primary.Accent};
    }
  }

  .strato-table-row-expandable + .strato-table-row-expanded {
    border-top: none;
  }
`;

/** @deprecated Shared FlattenSimpleInterpolation for tables rounded corner is going to be removed in the future.  */
export const sharedRoundedCornersCss = css`
  /** Rounded corners */
  .strato-table-header:first-child {
    /* overflow: hidden; */
    border-top-left-radius: ${Borders.Radius.Field.Default};
    border-top-right-radius: ${Borders.Radius.Field.Default};

    .strato-table-header-cell:first-child {
      border-top-left-radius: ${Borders.Radius.Field.Default};
    }
    .strato-table-header-cell:last-child {
      border-top-right-radius: ${Borders.Radius.Field.Default};
    }
  }
  .strato-table-row:last-child {
    .strato-table-cell:first-child {
      border-bottom-left-radius: ${Borders.Radius.Field.Default};
    }
    .strato-table-cell:last-child {
      border-bottom-right-radius: ${Borders.Radius.Field.Default};
    }
  }
`;
